def _load_overrides() -> None:
    global _OVERRIDES
    try:
        if os.path.exists(_OVERRIDE_PATH):
            with open(_OVERRIDE_PATH, 'r', encoding='utf-8') as f:
                data = json.load(f)
                if isinstance(data, dict):
                    _OVERRIDES = {str(k): str(v) for k, v in data.items() if isinstance(v, str)}
                else:
                    _OVERRIDES = {}
        else:
            _OVERRIDES = {}
    except Exception:
        _OVERRIDES = {}

def get_report_instructions(mode: str) -> str:
    m = (mode or "deep").lower()
    try:
        if not _OVERRIDES:
            _load_overrides()
        if m in _OVERRIDES and _OVERRIDES[m].strip():
            return _OVERRIDES[m]
    except Exception:
        pass
    # Fallback to original base implementation (captured before patching)
    try:
        if callable(_ORIG_GET_REPORT_INSTRUCTIONS):  # type: ignore[truthy-function]
            return _ORIG_GET_REPORT_INSTRUCTIONS(m)  # type: ignore[misc]
    except Exception:
        pass
    # Last resort: use base module's default instructions
    try:
        return _base_prompts._default_instructions(m)  # type: ignore[attr-defined]
    except Exception:
        return ""

def build_report_prompt(mode: str, query: str, top_k: int, docs: list[dict]) -> str:
    # Delegate to base; it will call our patched get_report_instructions
    return _base_prompts.build_report_prompt(mode, query, top_k, docs)

def build_judge_prompt(mode: str, query: str, results: list[dict]) -> str:
    # Delegate to base; it will call our patched get_report_instructions
    return _base_prompts.build_judge_prompt(mode, query, results)

class EmbeddingServiceClient:
    """Small adapter for the shared embedding-service batch contract.

    This class intentionally has no provider SDK or local-model fallback.  The
    service owns credentials and provider selection; callers only receive
    validated vectors in the one supported 3072-dimensional space.
    """

    def __init__(
        self,
        base_url: str | None = None,
        *,
        session: requests.Session | Any | None = None,
        timeout: float | None = None,
        max_retries: int | None = None,
        retry_backoff: float | None = None,
    ) -> None:
        configured_url = base_url if base_url is not None else os.environ.get("EMBEDDING_SERVICE_URL", "")
        if not configured_url or not configured_url.strip():
            raise EmbeddingServiceError(
                "EMBEDDING_SERVICE_URL is required; set a URL reachable from this Fungus runtime"
            )
        if any(character.isspace() for character in configured_url):
            raise EmbeddingServiceError("EMBEDDING_SERVICE_URL must be an absolute HTTP(S) URL without whitespace")
        try:
            parsed_url = urlparse(configured_url)
        except ValueError as exc:
            raise EmbeddingServiceError("EMBEDDING_SERVICE_URL must be an absolute HTTP(S) URL") from exc
        if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
            raise EmbeddingServiceError("EMBEDDING_SERVICE_URL must be an absolute HTTP(S) URL")
        self._base_url = configured_url.rstrip("/")
        self._session = session or requests.Session()
        self._timeout = float(timeout if timeout is not None else os.environ.get("EMBEDDING_HTTP_TIMEOUT", "30"))
        self._max_retries = max(0, int(max_retries if max_retries is not None else os.environ.get("EMBEDDING_HTTP_MAX_RETRIES", "2")))
        self._retry_backoff = max(0.0, float(retry_backoff if retry_backoff is not None else os.environ.get("EMBEDDING_HTTP_RETRY_BACKOFF", "0.5")))

    def encode(self, texts: Sequence[str]) -> list[list[float]]:
        """Embed text in order through ``POST /embed/batch`` only."""
        values = list(texts)
        if not values:
            return []
        response = self._post_with_retry("/embed/batch", {"texts": values})
        try:
            payload = response.json()
            vectors = payload["vectors"]
        except (KeyError, TypeError, ValueError) as exc:
            raise EmbeddingServiceError("embedding-service returned malformed batch response") from exc
        self._validate_vectors(vectors, len(values))
        return vectors

    def _post_with_retry(self, path: str, payload: dict[str, list[str]]) -> Any:
        attempts = self._max_retries + 1
        last_error: BaseException | None = None
        for attempt in range(attempts):
            try:
                response = self._session.post(
                    f"{self._base_url}{path}", json=payload, timeout=self._timeout
                )
                response.raise_for_status()
                return response
            except (requests.exceptions.ConnectionError, requests.exceptions.Timeout) as exc:
                last_error = exc
            except requests.exceptions.HTTPError as exc:
                status_code = getattr(exc.response, "status_code", None)
                if not isinstance(status_code, int) or status_code < 500:
                    raise EmbeddingServiceError(
                        f"embedding-service request failed with status {status_code}"
                    ) from exc
                last_error = exc
            if attempt < attempts - 1:
                time.sleep(self._retry_backoff * (attempt + 1))
        raise EmbeddingServiceUnavailable(
            f"embedding-service unavailable after {attempts} attempts; no local fallback is configured"
        ) from last_error

    @staticmethod
    def _validate_vectors(vectors: Any, expected_count: int) -> None:
        if not isinstance(vectors, list) or len(vectors) != expected_count:
            actual_count = len(vectors) if isinstance(vectors, list) else "non-list"
            raise EmbeddingServiceError(
                "embedding-service response count mismatch: "
                f"expected {expected_count}, got {actual_count}"
            )
        for vector in vectors:
            if not isinstance(vector, list) or len(vector) != EMBEDDING_DIMENSION:
                actual_dimension = len(vector) if isinstance(vector, list) else "non-vector"
                raise EmbeddingServiceError(
                    "embedding-service returned unexpected dimension: "
                    f"expected {EMBEDDING_DIMENSION}, got {actual_dimension}; reindex is required "
                    "before this vector space can be used."
                )

def encode(self, texts: Sequence[str]) -> list[list[float]]:
    """Embed text in order through ``POST /embed/batch`` only."""
    values = list(texts)
    if not values:
        return []
    response = self._post_with_retry("/embed/batch", {"texts": values})
    try:
        payload = response.json()
        vectors = payload["vectors"]
    except (KeyError, TypeError, ValueError) as exc:
        raise EmbeddingServiceError("embedding-service returned malformed batch response") from exc
    self._validate_vectors(vectors, len(values))
    return vectors

def _post_with_retry(self, path: str, payload: dict[str, list[str]]) -> Any:
    attempts = self._max_retries + 1
    last_error: BaseException | None = None
    for attempt in range(attempts):
        try:
            response = self._session.post(
                f"{self._base_url}{path}", json=payload, timeout=self._timeout
            )
            response.raise_for_status()
            return response
        except (requests.exceptions.ConnectionError, requests.exceptions.Timeout) as exc:
            last_error = exc
        except requests.exceptions.HTTPError as exc:
            status_code = getattr(exc.response, "status_code", None)
            if not isinstance(status_code, int) or status_code < 500:
                raise EmbeddingServiceError(
                    f"embedding-service request failed with status {status_code}"
                ) from exc
            last_error = exc
        if attempt < attempts - 1:
            time.sleep(self._retry_backoff * (attempt + 1))
    raise EmbeddingServiceUnavailable(
        f"embedding-service unavailable after {attempts} attempts; no local fallback is configured"
    ) from last_error

def _validate_vectors(vectors: Any, expected_count: int) -> None:
    if not isinstance(vectors, list) or len(vectors) != expected_count:
        actual_count = len(vectors) if isinstance(vectors, list) else "non-list"
        raise EmbeddingServiceError(
            "embedding-service response count mismatch: "
            f"expected {expected_count}, got {actual_count}"
        )
    for vector in vectors:
        if not isinstance(vector, list) or len(vector) != EMBEDDING_DIMENSION:
            actual_dimension = len(vector) if isinstance(vector, list) else "non-vector"
            raise EmbeddingServiceError(
                "embedding-service returned unexpected dimension: "
                f"expected {EMBEDDING_DIMENSION}, got {actual_dimension}; reindex is required "
                "before this vector space can be used."
            )

def load_embedding_backend() -> tuple[EmbeddingServiceClient, int]:
    """Return the sole Fungus embedding backend and its fixed vector contract."""
    return EmbeddingServiceClient(), EMBEDDING_DIMENSION

def load_embedding_model() -> EmbeddingServiceClient:
    """Compatibility helper for callers using the historical model accessor."""
    return load_embedding_backend()[0]

def _l2_normalize_rows(mat: np.ndarray) -> np.ndarray:
    n = np.linalg.norm(mat, axis=1, keepdims=True) + 1e-12
    return mat / n

def build_faiss_index(embs: np.ndarray, dim: int, force_cpu: bool = False) -> Optional[object]:
    _logger.info("build_faiss_index: dim=%d docs=%d faiss=%s", dim, int(embs.shape[0]), str(_FAISS_OK))
    if not _FAISS_OK:
        return None
    # For very small datasets, avoid IVF with huge cluster count
    n_docs = int(embs.shape[0])
    factory = "Flat" if n_docs < 4096 else "IVF4096,Flat"
    # Create index (cosine via inner product; caller should pass L2-normalized vectors if needed)
    index = faiss.index_factory(dim, factory, faiss.METRIC_INNER_PRODUCT)
    # Benchmarks can opt into CPU-only execution without changing runtime defaults.
    if force_cpu:
        _logger.info("build_faiss_index: force_cpu=True using_gpu=False")
    else:
        try:
            gpu_count = int(getattr(faiss, 'get_num_gpus', lambda: 0)())
        except Exception:
            gpu_count = 0
        if gpu_count > 0:
            try:
                _ = faiss.StandardGpuResources()
                index = faiss.index_cpu_to_all_gpus(index)
                _logger.info("build_faiss_index: faiss_gpus=%d using_gpu=True", gpu_count)
            except Exception as e:
                _logger.warning("build_faiss_index: failed to move index to GPU (faiss_gpus=%d): %s", gpu_count, e)
        else:
            _logger.info("build_faiss_index: faiss_gpus=0 using_gpu=False")
    # Normalize embeddings for cosine-like behavior with inner product
    embs = embs.astype(np.float32, copy=False)
    embs_n = _l2_normalize_rows(embs)
    # Train/add
    # Train only when index is trainable (IVF), skip for Flat
    try:
        index.train(embs_n)
    except Exception:
        pass
    index.add(embs_n)
    try:
        index.nprobe = 12
    except Exception:
        pass
    return index

def save_faiss_index(index, path: str) -> bool:
    """Save FAISS index to disk. GPU indexes are moved to CPU first."""
    if not _FAISS_OK or index is None:
        return False
    import os
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    try:
        # GPU index must be converted to CPU for serialization
        cpu_index = index
        try:
            cpu_index = faiss.index_gpu_to_cpu(index)
        except Exception:
            pass
        faiss.write_index(cpu_index, path)
        _logger.info("save_faiss_index: saved to %s", path)
        return True
    except Exception as e:
        _logger.warning("save_faiss_index: failed: %s", e)
        return False

def load_faiss_index(path: str, gpu: bool = True) -> Optional[object]:
    """Load FAISS index from disk, optionally move to GPU."""
    if not _FAISS_OK:
        return None
    import os
    if not os.path.exists(path):
        return None
    try:
        index = faiss.read_index(path)
        if gpu:
            try:
                gpu_count = int(getattr(faiss, 'get_num_gpus', lambda: 0)())
                if gpu_count > 0:
                    index = faiss.index_cpu_to_all_gpus(index)
                    _logger.info("load_faiss_index: moved to GPU (%d GPUs)", gpu_count)
            except Exception:
                pass
        try:
            index.nprobe = 12
        except Exception:
            pass
        _logger.info("load_faiss_index: loaded from %s (ntotal=%d)", path, int(index.ntotal))
        return index
    except Exception as e:
        _logger.warning("load_faiss_index: failed: %s", e)
        return None

def cosine_similarities_cpu(query_vec: np.ndarray, doc_embeddings: np.ndarray) -> np.ndarray:
    _logger.debug("cosine_similarities_cpu: docs=%d", int(doc_embeddings.shape[0]))
    q = query_vec.reshape(1, -1)
    q = q / (np.linalg.norm(q, axis=1, keepdims=True) + 1e-12)
    X = doc_embeddings / (np.linalg.norm(doc_embeddings, axis=1, keepdims=True) + 1e-12)
    return (q @ X.T).ravel()

def _now(retr: Any) -> float:
    source = getattr(retr, "time_source", None)
    return float(time.time() if source is None else source())

def calculate_pheromone_force(retr: Any, agent: Any) -> np.ndarray:
    _logger.debug("calculate_pheromone_force: agent_id=%s trails=%d", getattr(agent, 'id', '?'), len(getattr(retr, 'pheromone_trails', {})))
    if not retr.pheromone_trails:
        return np.zeros_like(agent.position)
    force = np.zeros_like(agent.position)
    current_docs = retr.find_nearest_documents(agent.position, k=1)
    if not current_docs:
        return force
    current_doc = current_docs[0][0]
    max_strength = 0.0
    best_direction = None
    for (doc_a, doc_b), strength in retr.pheromone_trails.items():
        if doc_a == current_doc.id:
            target_doc = next((d for d in retr.documents if d.id == doc_b), None)
            if target_doc is not None:
                direction = target_doc.embedding - agent.position
                if strength > max_strength:
                    max_strength = float(strength)
                    best_direction = direction
    if best_direction is not None and np.linalg.norm(best_direction) > 0:
        force = best_direction / np.linalg.norm(best_direction) * max_strength
    _logger.debug("calculate_pheromone_force: max_strength=%.4f", max_strength)
    return force

def decay_pheromones(retr: Any) -> None:
    keys_to_remove: List[Tuple[int, int]] = []
    for key in retr.pheromone_trails:
        retr.pheromone_trails[key] *= retr.pheromone_decay
        if retr.pheromone_trails[key] < 0.01:
            keys_to_remove.append(key)
    for key in keys_to_remove:
        del retr.pheromone_trails[key]
    if keys_to_remove:
        _logger.debug("decay_pheromones: pruned=%d remaining=%d", len(keys_to_remove), len(retr.pheromone_trails))

def update_document_relevance(retr: Any, query_embedding: np.ndarray) -> None:
    _logger.debug("update_document_relevance: start | docs=%d kw_lambda=%.3f",
                  len(getattr(retr, 'documents', [])), float(getattr(retr, 'kw_lambda', 0.0)))
    try:
        import torch  # type: ignore
        _TORCH_OK = True
    except Exception:
        torch = None  # type: ignore
        _TORCH_OK = False
    if not getattr(retr, "force_cpu", False) and _TORCH_OK and torch.cuda.is_available():
        with torch.no_grad():
            if retr._doc_emb_torch_norm is None:
                if retr._doc_emb_torch is None:
                    mat = torch.tensor(np.array([doc.embedding for doc in retr.documents], dtype=np.float32), device='cuda')
                    mat = mat.to(torch.float16)
                    retr._doc_emb_torch = mat
                retr._doc_emb_torch_norm = torch.nn.functional.normalize(retr._doc_emb_torch, p=2, dim=1)
            q = torch.tensor(query_embedding.astype(np.float32), device='cuda').to(torch.float16)
            qn = torch.nn.functional.normalize(q, p=2, dim=0)
            sims = (retr._doc_emb_torch_norm @ qn).float().cpu().numpy()
    else:
        from sklearn.metrics.pairwise import cosine_similarity  # type: ignore
        doc_embeddings = np.array([doc.embedding for doc in retr.documents])
        sims = cosine_similarity([query_embedding], doc_embeddings)[0]
    max_rel = 0.0
    for i, doc in enumerate(retr.documents):
        query_sim = float(sims[i])
        visit_bonus = min(doc.visit_count * 0.1, 0.5)
        time_bonus = 0.1 if _now(retr) - doc.last_visited < 1.0 else 0.0
        kw_bonus = 0.0
        if retr.kw_lambda and retr.kw_terms and getattr(doc, 'content', None):
            try:
                text = (doc.content or '').lower()
                if text:
                    hits = sum(1 for t in retr.kw_terms if t and t in text)
                    if hits:
                        kw_bonus = retr.kw_lambda * float(hits) / float(max(1, len(retr.kw_terms)))
            except Exception:
                kw_bonus = 0.0
        doc.relevance_score = query_sim + visit_bonus + time_bonus + kw_bonus
        if doc.relevance_score > max_rel:
            max_rel = float(doc.relevance_score)
    if retr.documents:
        mean_rel = float(np.mean([d.relevance_score for d in retr.documents]))
        top_rel = float(np.max([d.relevance_score for d in retr.documents]))
        _logger.debug("update_document_relevance: mean=%.4f max=%.4f top=%.4f", mean_rel, max_rel, top_rel)

def extract_relevance_network(retr: Any, min_strength: float = 0.1):
    # Sort documents by relevance
    relevant_docs = sorted(retr.documents, key=lambda d: d.relevance_score, reverse=True)
    retr.relevance_network.clear()
    for doc in relevant_docs:
        if doc.relevance_score > 0.1:
            retr.relevance_network.add_node(doc.id, content=(doc.content[:100] + "..."), relevance=doc.relevance_score, visits=doc.visit_count)
    edge_count = 0
    for (doc_a, doc_b), strength in retr.pheromone_trails.items():
        if strength > min_strength and doc_a in retr.relevance_network.nodes and doc_b in retr.relevance_network.nodes:
            retr.relevance_network.add_edge(doc_a, doc_b, strength=strength)
            edge_count += 1
    _logger.debug("extract_relevance_network: nodes=%d edges=%d", len(retr.relevance_network.nodes), edge_count)
    return [(doc, doc.relevance_score) for doc in relevant_docs if doc.relevance_score > 0.1]

def build_snapshot(docs_xy: np.ndarray,
                   relevances: List[float],
                   pheromone_trails: Dict[tuple, float],
                   meta: Optional[List[Dict[str, Any]]] = None,
                   agents_xy: Optional[np.ndarray] = None,
                   max_edges: int = 300) -> Dict[str, Any]:
    _logger.debug("build_snapshot: docs=%d trails=%d", int(len(docs_xy)), int(len(pheromone_trails or {})))
    edges = []
    if pheromone_trails is not None and len(docs_xy):
        dim = int(docs_xy.shape[1]) if hasattr(docs_xy, 'shape') and len(docs_xy.shape) == 2 else 2
        for (a, b), strength in sorted(pheromone_trails.items(), key=lambda x: x[1], reverse=True):
            if strength < 0.05:
                continue
            if a < len(docs_xy) and b < len(docs_xy):
                if dim >= 3:
                    x0, y0, z0 = docs_xy[a]
                    x1, y1, z1 = docs_xy[b]
                    edges.append({
                        "x0": float(x0), "y0": float(y0), "z0": float(z0),
                        "x1": float(x1), "y1": float(y1), "z1": float(z1),
                        "s": float(strength)
                    })
                else:
                    x0, y0 = docs_xy[a]
                    x1, y1 = docs_xy[b]
                    edges.append({"x0": float(x0), "y0": float(y0), "x1": float(x1), "y1": float(y1), "s": float(strength)})
            if len(edges) >= max_edges:
                break
    return {
        "documents": {"xy": docs_xy.tolist(), "relevance": [float(r) for r in relevances], "meta": meta or []},
        "agents": {"xy": (agents_xy.tolist() if agents_xy is not None else [])},
        "edges": edges,
    }

class MCPMRetriever:
    def __init__(self,
                 num_agents: int = 200,
                 max_iterations: int = 50,
                 pheromone_decay: float = 0.95,
                 exploration_bonus: float = 0.1,
                 embed_batch_size: int = 128,
                 build_faiss_after_add: bool = True,
                 force_cpu: bool = False,
                 embedding_backend: Optional[Tuple[Any, int]] = None,
                 time_source: Callable[[], float] | None = None):
        warnings.warn(
            "MCPMRetriever is deprecated as a facade. Internals are under embeddinggemma.mcmp.*",
            DeprecationWarning,
            stacklevel=2,
        )
        self.num_agents = int(num_agents)
        self.max_iterations = int(max_iterations)
        self.pheromone_decay = float(pheromone_decay)
        self.exploration_bonus = float(exploration_bonus)
        self.embed_batch_size = int(embed_batch_size)
        self.build_faiss_after_add = bool(build_faiss_after_add)
        self.force_cpu = bool(force_cpu)
        self.time_source = time.time if time_source is None else time_source
        if embedding_backend is None:
            self.embedding_model, self._expected_embedding_dim = load_embedding_backend()
        else:
            self.embedding_model, self._expected_embedding_dim = embedding_backend

        self.documents: List[Document] = []
        self.agents: List[Agent] = []
        self.pheromone_trails: Dict[Tuple[int, int], float] = {}
        self._current_query_embedding: Optional[np.ndarray] = None
        self._faiss_index = None
        self._embed_dim: Optional[int] = None
        self.log_every: int = 1

        # GPU cache used in mcmp.simulation.update_document_relevance if available
        self._doc_emb_torch = None  # type: ignore
        self._doc_emb_torch_norm = None  # type: ignore

        # Keyword knobs consumed by update_document_relevance
        self.kw_lambda: float = 0.0
        self.kw_terms: Set[str] = set()

        # Expose Agent constructor for simulation module
        # simulation.spawn_agents expects `retr.Agent` to be present
        self.Agent = Agent  # type: ignore[attr-defined]

    # ---- Persistence ----
    # Use absolute path based on package location so it works from any CWD
    _CACHE_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), ".fungus_cache")
    _FAISS_FILE = "faiss.index"
    _EMB_FILE = "embeddings.npz"
    _CHUNKS_FILE = "chunks.json"

    def _cache_path(self, filename: str) -> str:
        import os
        os.makedirs(self._CACHE_DIR, exist_ok=True)
        return os.path.join(self._CACHE_DIR, filename)

    def save_persistent_index(self) -> bool:
        """Save FAISS index + embeddings + chunk texts to disk."""
        import os
        if not self.documents:
            return False
        try:
            # Save FAISS index
            _save_faiss(self._faiss_index, self._cache_path(self._FAISS_FILE))
            # Save embeddings as compressed numpy
            mat = np.array([d.embedding for d in self.documents], dtype=np.float32)
            np.savez_compressed(self._cache_path(self._EMB_FILE), embeddings=mat)
            # Save chunk texts (for document reconstruction)
            import json
            texts = [d.content for d in self.documents]
            with open(self._cache_path(self._CHUNKS_FILE), "w", encoding="utf-8") as f:
                json.dump(texts, f, ensure_ascii=False)
            _logger.info("Persistent index saved: %d docs, %d dim", len(self.documents), mat.shape[1])
            return True
        except Exception as e:
            _logger.warning("Failed to save persistent index: %s", e)
            return False

    def load_persistent_index(self) -> bool:
        """Load FAISS index + embeddings + chunks from disk. Skips embedding computation."""
        import os, json
        faiss_path = self._cache_path(self._FAISS_FILE)
        emb_path = self._cache_path(self._EMB_FILE)
        chunks_path = self._cache_path(self._CHUNKS_FILE)

        # Embeddings + chunks are required; FAISS index is optional (rebuilt from embeddings)
        if not os.path.exists(emb_path) or not os.path.exists(chunks_path):
            return False

        try:
            # Load chunks
            with open(chunks_path, "r", encoding="utf-8") as f:
                texts = json.load(f)
            # Load embeddings
            data = np.load(emb_path)
            embs = data["embeddings"]
            if embs.ndim != 2:
                raise RuntimeError(
                    "Embedding cache rebuild required: cached embeddings must be a "
                    "two-dimensional matrix."
                )
            if len(texts) != embs.shape[0]:
                _logger.warning("Cache mismatch: %d texts vs %d embeddings", len(texts), embs.shape[0])
                return False
            cached_dim = int(embs.shape[1])
            if cached_dim != self._expected_embedding_dim:
                raise RuntimeError(
                    "Embedding cache rebuild required: cached dimension "
                    f"{cached_dim} does not match configured dimension "
                    f"{self._expected_embedding_dim}."
                )
            # Reconstruct documents
            self.documents = [
                Document(id=i, content=text, embedding=embs[i], metadata={})
                for i, text in enumerate(texts)
            ]
            self._embed_dim = cached_dim
            # Load FAISS index
            self._faiss_index = _load_faiss(faiss_path, gpu=not self.force_cpu)
            if self._faiss_index is None:
                # Rebuild from cached embeddings (fast, no re-embedding needed)
                self._faiss_index = _build_faiss(
                    embs, self._embed_dim, force_cpu=self.force_cpu
                )

            _logger.info("Persistent index loaded: %d docs, %d dim", len(self.documents), self._embed_dim)
            return True
        except RuntimeError as e:
            if str(e).startswith("Embedding cache rebuild required:"):
                raise
            _logger.warning("Failed to load persistent index: %s", e)
            return False
        except Exception as e:
            _logger.warning("Failed to load persistent index: %s", e)
            return False

    # ---- Public API ----
    def add_documents(self, docs: List[str], cache: bool = True) -> None:
        start_id = len(self.documents)
        contents = list(docs or [])
        embs: List[np.ndarray] = []
        bs = max(1, self.embed_batch_size)
        for i in range(0, len(contents), bs):
            batch = contents[i:i+bs]
            vecs = self.embedding_model.encode(batch)
            if len(vecs) != len(batch):
                raise RuntimeError(
                    "embedding-service response count does not match the request: "
                    f"expected {len(batch)}, got {len(vecs)}."
                )
            for vector in vecs:
                embedding = np.array(vector, dtype=np.float32)
                if embedding.ndim != 1 or embedding.shape[0] != self._expected_embedding_dim:
                    actual_dim = embedding.shape[0] if embedding.ndim == 1 else "non-vector"
                    raise RuntimeError(
                        "embedding-service response has unexpected dimension: "
                        f"expected dimension {self._expected_embedding_dim}, got {actual_dim}."
                    )
                embs.append(embedding)
        for i, (text, emb) in enumerate(zip(contents, embs)):
            self.documents.append(Document(id=start_id + i, content=text, embedding=emb, metadata={}))
        self._embed_dim = int(self.documents[0].embedding.shape[0]) if self.documents else None
        if self.build_faiss_after_add and self._embed_dim:
            try:
                mat = np.array([d.embedding for d in self.documents], dtype=np.float32)
                self._faiss_index = _build_faiss(
                    mat, int(self._embed_dim), force_cpu=self.force_cpu
                )
            except Exception as e:
                _logger.warning("FAISS index build failed: %s", e)
                self._faiss_index = None
        # Persist to disk for fast restart
        if cache and self.documents:
            self.save_persistent_index()

    def add_documents_incremental(self, docs: List[str]) -> Dict[str, int]:
        """Add only NEW documents (not already indexed). Returns stats."""
        existing = {d.content for d in self.documents}
        new_docs = [d for d in docs if d not in existing]
        if not new_docs:
            return {"new": 0, "total": len(self.documents), "skipped": len(docs)}
        self.add_documents(new_docs, cache=True)
        return {"new": len(new_docs), "total": len(self.documents), "skipped": len(docs) - len(new_docs)}

    def clear_documents(self) -> None:
        self.documents.clear()
        self._doc_emb_torch = None
        self._doc_emb_torch_norm = None
        self._faiss_index = None
        self._embed_dim = None

    def initialize_simulation(self, query: str) -> bool:
        if not self.documents:
            return False
        q = self.embedding_model.encode([query])[0]
        if len(q) != self._expected_embedding_dim:
            raise RuntimeError(
                "embedding-service response has unexpected dimension: "
                f"expected dimension {self._expected_embedding_dim}, got {len(q)}."
            )
        self._current_query_embedding = np.array(q, dtype=np.float32)
        self.spawn_agents(self._current_query_embedding)
        self.pheromone_trails = {}
        for d in self.documents:
            d.visit_count = 0
            d.last_visited = 0.0
            d.relevance_score = 0.0
        return True

    def step(self, n_steps: int = 1) -> Dict[str, Any]:
        if not self.documents or self._current_query_embedding is None or not self.agents:
            return {"error": "Simulation not initialized"}
        for _ in range(max(1, int(n_steps))):
            for a in self.agents:
                self.update_agent_position(a, 0)
                self.deposit_pheromones(a)
            self.update_document_relevance(self._current_query_embedding)
            self.decay_pheromones()
        avg_rel = float(np.mean([d.relevance_score for d in self.documents]))
        return {"avg_relevance": avg_rel, "steps": int(n_steps), "pheromone_trails": len(self.pheromone_trails)}

    def search(self, query: str, top_k: int = 10) -> Dict[str, Any]:
        if not self.documents:
            return {"results": []}
        return self.search_direct(query, top_k)

    def search_direct(self, query: str, top_k: int = 10) -> Dict[str, Any]:
        """Fast direct cosine search — no MCMP simulation needed.
        Uses FAISS if available, otherwise brute-force numpy."""
        if not self.documents:
            return {"results": []}
        q = np.array(self.embedding_model.encode([query])[0], dtype=np.float32)
        if q.ndim != 1 or q.shape[0] != self._expected_embedding_dim:
            actual_dim = q.shape[0] if q.ndim == 1 else "non-vector"
            raise RuntimeError(
                "embedding-service response has unexpected dimension: "
                f"expected dimension {self._expected_embedding_dim}, got {actual_dim}."
            )
        top_k = min(int(top_k), len(self.documents))

        # Try FAISS first
        if self._faiss_index is not None:
            try:
                distances, indices = _faiss_search(self._faiss_index, q, top_k)
                results = []
                for i, dist in zip(indices, distances):
                    i = int(i)
                    if 0 <= i < len(self.documents):
                        d = self.documents[i]
                        sim = max(0.0, float(dist))  # inner product = cosine for normalized
                        results.append({"content": d.content, "metadata": d.metadata, "relevance_score": sim})
                return {"results": results}
            except Exception as e:
                _logger.warning("search_direct FAISS failed, falling back: %s", e)

        # Brute-force cosine
        mat = np.array([d.embedding for d in self.documents], dtype=np.float32)
        mat_n = mat / (np.linalg.norm(mat, axis=1, keepdims=True) + 1e-12)
        q_n = q / (np.linalg.norm(q) + 1e-12)
        sims = mat_n @ q_n
        idx = np.argsort(-sims)[:top_k]
        return {"results": [
            {"content": self.documents[int(i)].content, "metadata": self.documents[int(i)].metadata, "relevance_score": float(sims[int(i)])}
            for i in idx
        ]}

    def get_visualization_snapshot(self,
                                   min_trail_strength: float = 0.05,
                                   max_edges: int = 300,
                                   method: str = "pca",
                                   whiten: bool = False,
                                   spread: float = 1.0,
                                   jitter: float = 0.0,
                                   dims: int = 2) -> Dict[str, Any]:
        if not self.documents:
            return {"documents": {"xy": [], "relevance": []}, "agents": {"xy": []}, "edges": []}
        embs = np.array([d.embedding for d in self.documents], dtype=np.float32)
        k = 3 if int(dims) == 3 else 2
        # Cache PCA basis for stable layout and consistent agent projection
        if not hasattr(self, "_viz_pca"):
            self._viz_pca = {}
        if self._viz_pca.get("k") != k:
            self._viz_pca.clear()
        if not self._viz_pca:
            coords, mean, comps, S = _pca_fit_transform(embs, n_components=k, whiten=bool(whiten))
            self._viz_pca = {"mean": mean, "comps": comps, "S": S, "k": k, "whiten": bool(whiten)}
        else:
            mean = self._viz_pca["mean"]
            comps = self._viz_pca["comps"]
            S = self._viz_pca.get("S")
            coords = (embs - mean) @ comps.T
            if bool(self._viz_pca.get("whiten")) and S is not None:
                s = S[:k]
                safe = np.array([sv if sv != 0 else 1.0 for sv in s])
                coords = coords / safe
        coords = coords if coords is not None else np.zeros((len(self.documents), k), dtype=np.float32)
        rels = [float(d.relevance_score) for d in self.documents]
        meta = [{
            "id": int(d.id),
            "score": float(d.relevance_score),
            "visits": int(d.visit_count),
            "snippet": (d.content or '')[:140] if hasattr(d, 'content') else ''
        } for d in self.documents]
        trails = {k: v for k, v in (self.pheromone_trails or {}).items() if float(v) >= float(min_trail_strength)}
        agents_xy = None
        try:
            if self.agents and self._viz_pca.get("comps") is not None:
                import numpy as _np
                mean = self._viz_pca["mean"]
                comps = self._viz_pca["comps"]
                S = self._viz_pca.get("S")
                A = _np.array([getattr(a, 'position', None) for a in self.agents if getattr(a, 'position', None) is not None], dtype=_np.float32)
                if A.size:
                    agents_xy = (A - mean) @ comps.T
                    if bool(self._viz_pca.get("whiten")) and S is not None:
                        s = S[:k]
                        safe = _np.array([sv if sv != 0 else 1.0 for sv in s], dtype=_np.float32)
                        agents_xy = agents_xy / safe
        except Exception:
            agents_xy = None
        return _build_snapshot(coords, rels, trails, meta, agents_xy, max_edges=int(max_edges))

    # ---- Public getters for frontend/live updates ----
    def get_query_embedding(self) -> Optional[np.ndarray]:
        return None if self._current_query_embedding is None else self._current_query_embedding.copy()

    def get_agent_positions(self) -> np.ndarray:
        return np.array([a.position for a in self.agents], dtype=np.float32) if self.agents else np.zeros((0, 0), dtype=np.float32)

    def get_doc_embeddings(self) -> np.ndarray:
        return np.array([d.embedding for d in self.documents], dtype=np.float32) if self.documents else np.zeros((0, 0), dtype=np.float32)

    def get_doc_relevances(self) -> List[Tuple[int, float]]:
        return [(d.id, float(d.relevance_score)) for d in self.documents]

    def get_pheromone_trails(self) -> Dict[Tuple[int, int], float]:
        return dict(self.pheromone_trails)

    def get_snapshot(self,
                     min_trail_strength: float = 0.05,
                     max_edges: int = 300,
                     method: str = "pca",
                     whiten: bool = False,
                     dims: int = 2) -> Dict[str, Any]:
        return self.get_visualization_snapshot(
            min_trail_strength=min_trail_strength,
            max_edges=max_edges,
            method=method,
            whiten=whiten,
            dims=dims,
        )

    # ---- Delegates consumed by simulation.* ----
    def spawn_agents(self, query_embedding: np.ndarray) -> None:
        _spawn_agents(self, query_embedding)

    def update_agent_position(self, agent: Agent, iteration: int) -> None:
        _update_agent_position(self, agent, iteration)

    def deposit_pheromones(self, agent: Agent) -> None:
        _deposit_pheromones(self, agent)

    def decay_pheromones(self) -> None:
        _decay_pheromones(self)

    def update_document_relevance(self, query_embedding: np.ndarray) -> None:
        _update_document_relevance(self, query_embedding)

    # ---- Helpers for simulation.* ----
    def find_nearest_documents(self, position: np.ndarray, k: int = 3) -> List[Tuple[Document, float]]:
        if not self.documents:
            return []
        k = min(int(k), len(self.documents))
        pos = np.array(position, dtype=np.float32).reshape(1, -1)

        # Fast path: use FAISS index if available (O(log n) vs O(n))
        if self._faiss_index is not None:
            try:
                similarities, indices = _faiss_search(self._faiss_index, pos.squeeze(), k)
                results = []
                for i, similarity in zip(indices, similarities):
                    i = int(i)
                    if 0 <= i < len(self.documents):
                        results.append((self.documents[i], float(similarity)))
                return results
            except Exception:
                pass  # Fall through to brute-force

        # Fallback: brute-force cosine similarity (slow for large N)
        mat = np.array([d.embedding for d in self.documents], dtype=np.float32)
        pos_n = pos.squeeze() / (np.linalg.norm(pos) + 1e-12)
        mat_n = mat / (np.linalg.norm(mat, axis=1, keepdims=True) + 1e-12)
        sims = mat_n @ pos_n
        idx = np.argsort(-sims)[:k]
        return [(self.documents[int(i)], float(sims[int(i)])) for i in idx]

def _cache_path(self, filename: str) -> str:
    import os
    os.makedirs(self._CACHE_DIR, exist_ok=True)
    return os.path.join(self._CACHE_DIR, filename)

def add_documents(self, docs: List[str], cache: bool = True) -> None:
    start_id = len(self.documents)
    contents = list(docs or [])
    embs: List[np.ndarray] = []
    bs = max(1, self.embed_batch_size)
    for i in range(0, len(contents), bs):
        batch = contents[i:i+bs]
        vecs = self.embedding_model.encode(batch)
        if len(vecs) != len(batch):
            raise RuntimeError(
                "embedding-service response count does not match the request: "
                f"expected {len(batch)}, got {len(vecs)}."
            )
        for vector in vecs:
            embedding = np.array(vector, dtype=np.float32)
            if embedding.ndim != 1 or embedding.shape[0] != self._expected_embedding_dim:
                actual_dim = embedding.shape[0] if embedding.ndim == 1 else "non-vector"
                raise RuntimeError(
                    "embedding-service response has unexpected dimension: "
                    f"expected dimension {self._expected_embedding_dim}, got {actual_dim}."
                )
            embs.append(embedding)
    for i, (text, emb) in enumerate(zip(contents, embs)):
        self.documents.append(Document(id=start_id + i, content=text, embedding=emb, metadata={}))
    self._embed_dim = int(self.documents[0].embedding.shape[0]) if self.documents else None
    if self.build_faiss_after_add and self._embed_dim:
        try:
            mat = np.array([d.embedding for d in self.documents], dtype=np.float32)
            self._faiss_index = _build_faiss(
                mat, int(self._embed_dim), force_cpu=self.force_cpu
            )
        except Exception as e:
            _logger.warning("FAISS index build failed: %s", e)
            self._faiss_index = None
    # Persist to disk for fast restart
    if cache and self.documents:
        self.save_persistent_index()

def add_documents_incremental(self, docs: List[str]) -> Dict[str, int]:
    """Add only NEW documents (not already indexed). Returns stats."""
    existing = {d.content for d in self.documents}
    new_docs = [d for d in docs if d not in existing]
    if not new_docs:
        return {"new": 0, "total": len(self.documents), "skipped": len(docs)}
    self.add_documents(new_docs, cache=True)
    return {"new": len(new_docs), "total": len(self.documents), "skipped": len(docs) - len(new_docs)}

def initialize_simulation(self, query: str) -> bool:
    if not self.documents:
        return False
    q = self.embedding_model.encode([query])[0]
    if len(q) != self._expected_embedding_dim:
        raise RuntimeError(
            "embedding-service response has unexpected dimension: "
            f"expected dimension {self._expected_embedding_dim}, got {len(q)}."
        )
    self._current_query_embedding = np.array(q, dtype=np.float32)
    self.spawn_agents(self._current_query_embedding)
    self.pheromone_trails = {}
    for d in self.documents:
        d.visit_count = 0
        d.last_visited = 0.0
        d.relevance_score = 0.0
    return True

def step(self, n_steps: int = 1) -> Dict[str, Any]:
    if not self.documents or self._current_query_embedding is None or not self.agents:
        return {"error": "Simulation not initialized"}
    for _ in range(max(1, int(n_steps))):
        for a in self.agents:
            self.update_agent_position(a, 0)
            self.deposit_pheromones(a)
        self.update_document_relevance(self._current_query_embedding)
        self.decay_pheromones()
    avg_rel = float(np.mean([d.relevance_score for d in self.documents]))
    return {"avg_relevance": avg_rel, "steps": int(n_steps), "pheromone_trails": len(self.pheromone_trails)}

def search(self, query: str, top_k: int = 10) -> Dict[str, Any]:
