def build_judge_prompt(mode: str, query: str, results: list[dict]) -> str:
    m = (mode or "steering").lower()
    items = []
    for it in (results or []):
        try:
            items.append({
                'doc_id': int(it.get('id', it.get('doc_id', -1))),
                'score': float(it.get('score', 0.0)),
                'content': (it.get('content') or '')[:1200],
            })
        except Exception:
            continue
    instr = get_report_instructions(m)
    schema = judge_schema_hint()
    return (
        f"Mode: {m}\nQuery: {query}\n\n" +
        instr + "\n" +
        "Evaluate the following code chunks for relevance to the query. "
        "Mark entry_point for main functions, API routes, or top-level orchestrators.\n\n" +
        __import__('json').dumps({'chunks': items}, ensure_ascii=False) + "\n\n" +
        schema
    )

def parse_code_with_ast(file_path: str) -> List[Dict[str, Any]]:
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            source_code = f.read()
        tree = ast.parse(source_code)
        chunks = []
        current = {
            'file': os.path.relpath(file_path, 'src'),
            'type': 'file',
            'content': '',
            'metadata': {
                'start_line': 1,
                'end_line': 0,
                'ast_nodes': []
            }
        }
        for node in ast.walk(tree):
            node_str = ast.get_source_segment(source_code, node)
            if not node_str:
                continue
            start_line = getattr(node, 'lineno', 1)
            end_line = getattr(node, 'end_lineno', start_line)
            current['content'] += f"\n{node_str}"
            current['metadata']['ast_nodes'].append({
                'type': type(node).__name__,
                'start_line': start_line,
                'end_line': end_line,
                'name': getattr(node, 'name', None) if hasattr(node, 'name') else None
            })
            current['metadata']['end_line'] = end_line
        if current['content'].strip():
            current['metadata']['size'] = len(current['content'])
            chunks.append(current)
        return chunks
    except SyntaxError:
        return fallback_chunking(file_path)
    except Exception:
        return []

def fallback_chunking(file_path: str, lines_per_chunk: int = 20) -> List[Dict[str, Any]]:
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
        out: List[Dict[str, Any]] = []
        for i in range(0, len(lines), lines_per_chunk):
            chunk = ''.join(lines[i:i + lines_per_chunk])
            if not chunk.strip():
                continue
            out.append({
                'file': os.path.relpath(file_path, 'src'),
                'type': 'line_chunk',
                'content': chunk.strip(),
                'metadata': {
                    'start_line': i + 1,
                    'end_line': min(i + lines_per_chunk, len(lines)),
                    'size': len(chunk)
                }
            })
        return out
    except Exception:
        return []

def _write_prompt(path: Optional[str], prompt: str) -> None:
    if not path:
        return
    prompt_path = Path(path)
    prompt_path.parent.mkdir(parents=True, exist_ok=True)
    prompt_path.write_text(prompt, encoding="utf-8")

def _response_text(response: Any) -> str:
    choices = getattr(response, "choices", None)
    if not choices:
        raise RuntimeError("OpenFang returned no completion choices")
    message = getattr(choices[0], "message", None)
    content = getattr(message, "content", None)
    if not isinstance(content, str) or not content:
        raise RuntimeError("OpenFang returned an empty completion")
    return content

def generate_judge_text(
    prompt: str,
    *,
    system: Optional[str] = None,
    save_prompt_path: Optional[str] = None,
) -> str:
    """Generate a judge result through the fixed OpenFang judge role."""
    return _generate_completion(
        _JUDGE_ROLE,
        prompt,
        system=system,
        save_prompt_path=save_prompt_path,
    )

def load_index(persist_dir: str, vector_store: QdrantVectorStore, embed_model):
    from llama_index.core import load_index_from_storage
    _logger.info("load_index: dir=%s", persist_dir)
    storage_context = StorageContext.from_defaults(persist_dir=persist_dir, vector_store=vector_store)
    try:
        return load_index_from_storage(storage_context=storage_context, embed_model=embed_model)
    except Exception:
        return VectorStoreIndex.from_vector_store(vector_store=vector_store, storage_context=storage_context, embed_model=embed_model)

def _collect_py_documents(root_dir: str, max_files: int = 300, max_chars: int = 4000) -> List[str]:
    docs: List[str] = []
    count = 0
    for dirpath, _dirnames, filenames in os.walk(root_dir):
        for fn in filenames:
            if not fn.endswith(".py"):
                continue
            try:
                with open(os.path.join(dirpath, fn), "r", encoding="utf-8", errors="ignore") as f:
                    txt = f.read()
                    if txt:
                        docs.append(txt[:max_chars])
                        count += 1
                        if count >= max_files:
                            return docs
            except Exception:
                continue
    return docs

def _sha1_of_file(path: str) -> str:
    try:
        h = hashlib.sha1()
        with open(path, 'rb') as f:
            for block in iter(lambda: f.read(1024 * 1024), b""):
                h.update(block)
        return h.hexdigest()
    except Exception:
        return ""

def _parse_chunk_header_line(first_line: str) -> tuple[str | None, int | None, int | None, int | None]:
    try:
        if not first_line.startswith('# file:'):
            return None, None, None, None
        parts = [p.strip() for p in first_line[1:].split('|')]
        file_part = parts[0].split(':', 1)[1].strip() if len(parts) > 0 and ':' in parts[0] else None
        lines_part = parts[1].split(':', 1)[1].strip() if len(parts) > 1 and ':' in parts[1] else None
        win_part = parts[2].split(':', 1)[1].strip() if len(parts) > 2 and ':' in parts[2] else None
        a, b = None, None
        if lines_part and '-' in lines_part:
            try:
                a = int(lines_part.split('-')[0].strip())
                b = int(lines_part.split('-')[1].strip())
            except Exception:
                a, b = None, None
        w = None
        try:
            if win_part:
                w = int(win_part)
        except Exception:
            w = None
        return file_part, a, b, w
    except Exception:
        return None, None, None, None

