def snippet_for(item: Dict[str, Any], q: str, radius: int = 5) -> str:
    text = item.get('content') or ''
    lines = text.splitlines()
    try:
        pattern = re.compile(re.escape(q), re.IGNORECASE)
    except Exception:
        pattern = None
    idx = None
    if pattern:
        for i, ln in enumerate(lines):
            if pattern.search(ln):
                idx = i
                break
    if idx is None:
        return "\n".join(lines[:min(10, len(lines))])
    s = max(0, idx - radius)
    e = min(len(lines), idx + radius + 1)
    return "\n".join(lines[s:e])

def _file_sha1(path: str) -> str:
    try:
        h = hashlib.sha1()
        with open(path, 'rb') as f:
            for block in iter(lambda: f.read(1024 * 1024), b""):
                h.update(block)
        return h.hexdigest()
    except Exception:
        return ""

def _cache_key(path: str, windows: List[int]) -> str:
    rel = os.path.relpath(path).replace(os.sep, "_")
    win_key = "-".join(str(int(w)) for w in sorted(set(int(w) for w in windows)))
    sha = _file_sha1(path)
    return os.path.join(CACHE_DIR, f"{rel}.{sha}.{win_key}.jsonl")

def _load_cached_chunks(path: str, windows: List[int]) -> List[str]:
    c = _cache_key(path, windows)
    try:
        if os.path.exists(c):
            with open(c, 'r', encoding='utf-8') as f:
                return [line.rstrip("\n").replace('\\n', '\n') for line in f]
    except Exception:
        return []
    return []

def _save_cached_chunks(path: str, windows: List[int], chunks: List[str]) -> None:
    c = _cache_key(path, windows)
    try:
        os.makedirs(os.path.dirname(c), exist_ok=True)
        with open(c, 'w', encoding='utf-8') as f:
            for ch in chunks:
                f.write(ch.replace('\n', '\\n') + '\n')
    except Exception:
        pass

def _chunk_line_windows(path: str, windows: List[int]) -> List[str]:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except Exception:
        return []
    chunks: List[str] = []
    total = len(lines)
    rel = os.path.relpath(path)
    for w in windows:
        step = max(1, int(w))
        for i in range(0, total, step):
            start = i + 1
            end = min(i + step, total)
            body = ''.join(lines[i:end])
            if body.strip():
                header = _path_boost_header(rel, start, end, step)
                chunks.append(header + body)
    return chunks

def _chunk_python_file_ast(path: str, windows: List[int]) -> List[str]:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            source = f.read()
    except Exception:
        return []
    try:
        tree = ast.parse(source)
    except Exception:
        return []
    lines = source.splitlines(keepends=True)
    total = len(lines)
    rel = os.path.relpath(path)
    max_window = max(1, max(int(w) for w in windows) if windows else 1000)

    def slice_block(start_line: int, end_line: int) -> List[str]:
        start_idx = max(1, start_line)
        end_idx = min(end_line, total)
        body = ''.join(lines[start_idx - 1:end_idx])
        if not body.strip():
            return []
        # If block is small enough, keep as one chunk
        if (end_idx - start_idx + 1) <= max_window:
            header = _path_boost_header(rel, start_idx, end_idx, max_window)
            return [header + body]
        # Otherwise split into windowed sub-chunks
        chunks_local: List[str] = []
        step = max_window
        overlap = max(0, int(0.2 * step))
        i = start_idx - 1
        while i < end_idx:
            s = i + 1
            e = min(i + step, end_idx)
            sub = ''.join(lines[s - 1:e])
            if sub.strip():
                header = _path_boost_header(rel, s, e, max_window)
                chunks_local.append(header + sub)
            if e >= end_idx:
                break
            i = e - overlap
        return chunks_local

    chunks: List[str] = []
    # Module-level docstring and imports as a header chunk (optional)
    mod_start = 1
    mod_end = total
    if getattr(tree, 'body', []):
        first_node = tree.body[0]
        last_node = tree.body[-1]
        try:
            mod_start = getattr(first_node, 'lineno', 1)
            mod_end = getattr(last_node, 'end_lineno', total)
        except Exception:
            mod_start, mod_end = 1, total

    # Collect class and function nodes
    nodes: List[ast.AST] = []
    for n in tree.body:
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            nodes.append(n)

    if not nodes:
        return slice_block(1, total)

    for n in nodes:
        try:
            s = getattr(n, 'lineno', None)
            e = getattr(n, 'end_lineno', None)
        except Exception:
            s, e = None, None
        if s is None or e is None:
            # Fallback to full file slice if positions are unavailable
            return slice_block(1, total)
        chunks.extend(slice_block(int(s), int(e)))

    return chunks

def chunk_python_file(path: str, windows: List[int]) -> List[str]:
    # Try AST-based chunking first for semantically coherent chunks
    chunks_ast = _chunk_python_file_ast(path, windows)
    if chunks_ast:
        return chunks_ast
    # Fallback to simple line-window chunking
    return _chunk_line_windows(path, windows)

def list_code_files(root_dir: str, max_files: int, exclude_dirs: List[str] = None) -> List[str]:
    files: List[str] = []
    count = 0
    for root, dirs, filenames in os.walk(root_dir):
        if exclude_dirs:
            dirs[:] = [d for d in dirs if not any(ex in os.path.join(root, d) for ex in exclude_dirs)]
        for fn in filenames:
            if _is_indexable(fn):
                files.append(os.path.join(root, fn))
                count += 1
                if max_files and count >= max_files:
                    return files
    return files

def collect_codebase_chunks(root_dir: str, windows: List[int], max_files: int, exclude_dirs: List[str] = None, workers: int | None = None) -> List[str]:
    files_to_process = list_code_files(root_dir, max_files, exclude_dirs)
    docs: List[str] = []
    max_workers = workers if (workers and workers > 0) else max(4, min(32, (os.cpu_count() or 8) * 2))
    with ThreadPoolExecutor(max_workers=max_workers) as ex:
        futures: Dict[Any, str] = {}
        for p in files_to_process:
            cached = _load_cached_chunks(p, windows)
            if cached:
                docs.extend(cached)
            else:
                futures[ex.submit(chunk_python_file, p, windows)] = p
        for fut in as_completed(futures):
            p = futures[fut]
            try:
                chunks = fut.result()
            except Exception:
                chunks = []
            if chunks:
                docs.extend(chunks)
                _save_cached_chunks(p, windows, chunks)
    return docs

def _normalize(v: np.ndarray) -> np.ndarray:
    n = np.linalg.norm(v, axis=1, keepdims=True) + 1e-12
    return v / n

def _extract_source(meta: Dict[str, Any], content: str) -> str:
    src = (meta or {}).get('file_path') if isinstance(meta, dict) else None
    if not src:
        import re
        m = re.search(r"^# file: (.+?) \| lines:", content or "", re.MULTILINE)
        if m:
            src = m.group(1)
    return src or "unknown"

def quick_search_with_mcmp(settings: Dict[str, Any], query_text: str, top_k: int) -> Dict[str, Any]:
    try:
        from embeddinggemma.mcmp_rag import MCPMRetriever  # type: ignore
    except Exception:
        try:
            from mcmp_rag import MCPMRetriever  # type: ignore
        except Exception as e:
            return {"error": f"MCPMRetriever unavailable: {e}"}

    from .corpus import collect_codebase_chunks, list_code_files

    corp = {
        "docs": [],
        "discovered_files": [],
        "loaded_files": [],
    }
    if settings.get('use_repo', True):
        corp["discovered_files"] = list_code_files('src', int(settings.get('max_files', 200)), settings.get('exclude_dirs', []))
        corp["docs"] = collect_codebase_chunks('src', settings.get('windows', [100, 200, 300]), int(settings.get('max_files', 200)), settings.get('exclude_dirs', []))
    else:
        rf = (settings.get('root_folder') or '').strip()
        if rf and os.path.isdir(rf):
            corp["discovered_files"] = list_code_files(rf, int(settings.get('max_files', 200)), settings.get('exclude_dirs', []))
            corp["docs"] = collect_codebase_chunks(rf, settings.get('windows', [100, 200, 300]), int(settings.get('max_files', 200)), settings.get('exclude_dirs', []))
    docs = corp.get('docs', [])
    if not docs:
        return {"error": "No documents found for quick search"}

    retr = MCPMRetriever(
        num_agents=int(settings.get('num_agents', 100)),
        max_iterations=int(settings.get('max_iterations', 20)),
        exploration_bonus=float(settings.get('exploration_bonus', 0.1)),
        pheromone_decay=float(settings.get('pheromone_decay', 0.95)),
        embed_batch_size=int(settings.get('embed_bs', 64))
    )
    try:
        retr.add_documents(docs)
        res = retr.search(str(query_text), top_k=int(top_k))
    except Exception as e:
        return {"error": f"search failed: {e}"}
    return {"results": res.get('results', []), "docs_count": len(docs)}

def _normalize_query_text(text: str) -> str:
    try:
        t = (text or "").strip().lower()
        t = re.sub(r"[^a-z0-9]+", " ", t)
    except re.error:
        t = (text or "").strip().lower()
    t = re.sub(r"\s+", " ", t).strip()
    stop = {
        "the","a","an","is","are","be","to","of","in","on","for","and","or","with","how","what","where","when","which","that",
        "does","do","can","i","we","you","it","this","these","those","about","use","used","using","run","start","guide"
    }
    tokens = [w for w in t.split() if w not in stop]
    return " ".join(tokens)

def _trigram_set(text: str) -> set:
    t = _normalize_query_text(text)
    if not t:
        return set()
    tokens = t.split()
    if len(tokens) < 3:
        return set([" ".join(tokens)]) if tokens else set()
    grams = set()
    for i in range(len(tokens) - 2):
        grams.add(" ".join(tokens[i:i+3]))
    return grams

